import{_ as s,a0 as i,w as p,s as y,I as r,x as a,a1 as o,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用开源搜索引擎 YaCy 的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"使用开源搜索引擎 YaCy 的技巧 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用开源搜索引擎 YaCy 的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用开源搜索引擎 YaCy 的技巧 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200210 Top hacks for the YaCy open source search engine","title":"使用开源搜索引擎 YaCy 的技巧","tag":"202002","desc":""},"relativePath":"202002/20200210 Top hacks for the YaCy open source search engine.md","filePath":"[post].md"}'),u={name:"202002/20200210 Top hacks for the YaCy open source search engine.md"};function d(C,t,m,f,Y,b){const e=i("Link");return p(),y("div",null,[t[28]||(t[28]=r("h1",{id:"使用开源搜索引擎-yacy-的技巧",tabindex:"-1"},[a("使用开源搜索引擎 YaCy 的技巧 "),r("a",{class:"header-anchor",href:"#使用开源搜索引擎-yacy-的技巧","aria-label":"Permalink to “使用开源搜索引擎 YaCy 的技巧”"},"​")],-1)),t[29]||(t[29]=r("blockquote",null,[r("p",null,"无需适应其他人的眼光，而是使用 YaCY 搜索引擎定义你想要的互联网。")],-1)),t[30]||(t[30]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202002/23/115822jqkdyjwzdqwdad0y.jpg",alt:""})],-1)),r("p",null,[t[2]||(t[2]=a("在我以前介绍 ",-1)),o(e,{href:"https://linux.cn/article-11905-1.html"},{default:n(()=>[...t[0]||(t[0]=[a("YaCy 入门",-1)])]),_:1}),t[3]||(t[3]=a("的文章中讲述过 ",-1)),o(e,{href:"https://yacy.net/"},{default:n(()=>[...t[1]||(t[1]=[a("YaCy",-1)])]),_:1}),t[4]||(t[4]=a(" 这个",-1)),t[5]||(t[5]=r("ruby",null,[a("对等"),r("rt",null,"peer-to-peer")],-1)),t[6]||(t[6]=a("式的搜索引擎是如何安装和使用的。YaCy 最令人兴奋的一点就是它事实上是一个本地客户端，全球范围内的每一个 YaCy 用户都是构成整个这个分布式搜索引擎架构的一个节点，这意味着每个用户都可以掌控自己的互联网搜索体验。",-1))]),r("p",null,[t[8]||(t[8]=a("Google 曾经提供过 google.com/linux 这样的主题简便方式以便快速筛选出和 Linux 相关的搜索内容，这个小功能受到了很多人的青睐，但 Google 最终还是在 2011 年的时候把它",-1)),o(e,{href:"https://www.linuxquestions.org/questions/linux-news-59/is-there-no-more-linux-google-884306/"},{default:n(()=>[...t[7]||(t[7]=[a("下线",-1)])]),_:1}),t[9]||(t[9]=a("了。",-1))]),t[31]||(t[31]=l('<p>而 YaCy 则让自定义搜索引擎变得可能。</p><h3 id="自定义-yacy" tabindex="-1">自定义 YaCy <a class="header-anchor" href="#自定义-yacy" aria-label="Permalink to “自定义 YaCy”">​</a></h3><p>YaCy 安装好之后，只需要访问 <code>localhost:8090</code> 就可以使用了。要自定义搜索引擎，只需要点击右上角的“<ruby>管理<rt>Administration</rt></ruby>”按钮（它可能隐藏在小屏幕的菜单图标中）。</p><p>你可以在管理面板中配置 YaCy 对系统资源的使用策略，以及如何跟其它的 YaCy 客户端进行交互。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-profiles.jpg" alt="YaCy profile selector" title="YaCy profile selector"></p><p>例如，点击侧栏中的“<ruby>第一步<rt>First steps</rt></ruby>”按钮可以配置备用端口，以及设置 YaCy 对内存和硬盘的使用量；而“<ruby>监控<rt>Monitoring</rt></ruby>”面板则可以监控 YaCy 的运行状况。大多数功能都只需要在面板上点击几下就可以完成了，例如以下几个常用的功能。</p><h3 id="内网搜索应用" tabindex="-1">内网搜索应用 <a class="header-anchor" href="#内网搜索应用" aria-label="Permalink to “内网搜索应用”">​</a></h3>',7)),r("p",null,[t[11]||(t[11]=a("目前市面上也有不少公司推出了",-1)),o(e,{href:"https://en.wikipedia.org/wiki/Vivisimo"},{default:n(()=>[...t[10]||(t[10]=[a("内网搜索应用",-1)])]),_:1}),t[12]||(t[12]=a("，而 YaCy 可以免费为你提供一个。对于能够通过 HTTP、FTP、Samba 等协议访问的文件，YaCy 都可以进行索引，因此无论是作为私人的文件搜索还是企业内部的本地共享文件搜索，YaCy 都可以实现。它可以让内部网络中的用户使用你个人的 YaCy 实例来查找共享文件，于此同时保持对内部网络以外的用户不可见。",-1))]),t[32]||(t[32]=l('<h3 id="网络配置" tabindex="-1">网络配置 <a class="header-anchor" href="#网络配置" aria-label="Permalink to “网络配置”">​</a></h3><p>YaCy 在默认情况下就支持隐私和隔离。点击“<ruby>用例与账号<rt>Use Case &amp; Account</rt></ruby>”页面顶部的“<ruby>网络配置<rt>Network Configuration</rt></ruby>”链接，即可进入网络配置面板设置对等网络。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-network-config.jpg" alt="YaCy network configuration" title="YaCy network configuration"></p><h3 id="爬取站点" tabindex="-1">爬取站点 <a class="header-anchor" href="#爬取站点" aria-label="Permalink to “爬取站点”">​</a></h3><p>YaCy 的分布式运作方式决定了它对页面的爬取是由用户驱动的。并没有一个大型公司对整个互联网上的所有可访问页面都进行搜索，对于 YaCy 来说也是这样，一个站点只有在被用户指定爬取的前提下，才会被 YaCy 爬取并进入索引。</p><p>YaCy 客户端提供了两种爬取页面的方式：你可以手动爬取，并让 YaCy 根据建议去爬取。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-advanced-crawler.jpg" alt="YaCy advanced crawler" title="YaCy advanced crawler"></p><h4 id="手动爬取" tabindex="-1">手动爬取 <a class="header-anchor" href="#手动爬取" aria-label="Permalink to “手动爬取”">​</a></h4><p>手动爬取是指由用户输入指定的网站 URL 并启动 YaCy 的爬虫任务。只需要点击“<ruby>高级爬虫<rt>Advanced Crawler</rt></ruby>”并输入计划爬取的若干 URL，然后选择页面底部的“<ruby>进行远程索引<rt>Do Remote indexing</rt></ruby>”选项，这个选项会让客户端向互联网广播它要索引的 URL，可选地接受这些请求的客户端可以帮助你爬取这些 URL。</p><p>点击页面底部的“<ruby>开始新爬虫任务<rt>Start New Crawl Job</rt></ruby>”按钮就可以开始进行爬取了，我就是这样对一些常用和有用站点进行爬取和索引的。</p><p>爬虫任务启动之后，YaCy 会将这些 URL 对应的页面在本地生成和存储索引。在高级模式下，也就是本地计算机允许 8090 端口流量进出时，全网的 YaCy 用户都可以使用到这一份索引。</p><h4 id="加入爬虫网络" tabindex="-1">加入爬虫网络 <a class="header-anchor" href="#加入爬虫网络" aria-label="Permalink to “加入爬虫网络”">​</a></h4><p>尽管一些非常敬业的 YaCy 高级用户已经强迫症般地在互联网上爬取了很多页面，但对于全网浩如烟海的页面而言也只是沧海一粟。单个用户所拥有的资源远不及很多大公司的网络爬虫，但大量 YaCy 用户如果联合起来成为一个社区，能产生的力量就大得多了。只要开启了 YaCy 的爬虫请求广播功能，就可以让其它客户端参与进来爬取更多页面。</p><p>只需要在“<ruby>高级爬虫<rt>Advanced Crawler</rt></ruby>”面板中点击页面顶部的“<ruby>远程爬取<rt>Remote Crawling</rt></ruby>”，勾选“<ruby>加载<rt>Load</rt></ruby>”旁边的复选框，就可以让你的客户端接受其它人发来的爬虫任务请求了。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-remote-crawl-accept.jpg" alt="YaCy remote crawling" title="YaCy remote crawling"></p><h3 id="yacy-监控相关" tabindex="-1">YaCy 监控相关 <a class="header-anchor" href="#yacy-监控相关" aria-label="Permalink to “YaCy 监控相关”">​</a></h3><p>YaCy 除了作为一个非常强大的搜索引擎，还提供了很丰富的主题和用户体验。你可以在“<ruby>监控<rt>Monitor</rt></ruby>”面板中监控 YaCy 客户端的网络运行状况，甚至还可以了解到有多少人从 YaCy 社区中获取到了自己所需要的东西。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-monitor.jpg" alt="YaCy monitoring screen" title="YaCy monitoring screen"></p><h3 id="搜索引擎发挥了作用" tabindex="-1">搜索引擎发挥了作用 <a class="header-anchor" href="#搜索引擎发挥了作用" aria-label="Permalink to “搜索引擎发挥了作用”">​</a></h3><p>你使用 YaCy 的时间越长，就越会思考搜索引擎如何改变自己的视野，因为你对互联网的体验很大一部分来自于你在搜索引擎中一次次简单查询的结果。实际上，当你和不同行业的人交流时，可能会注意到每个人对“互联网”的理解都有所不同。有些人会认为，互联网的搜索引擎中充斥着各种广告和推广，同时也仅仅能从搜索结果中获取到有限的信息。例如，假设有人不断搜索关于关键词 X 的内容，那么大部分商业搜索引擎都会在搜索结果中提高关键词 X 的权重，但与此同时，另一个关键词 Y 的权重则会相对降低，从而让关键词 Y 被淹没在搜索结果当中，即使这样对完成特定任务更好。</p><p>就像在现实生活中一样，走出虚拟的世界视野会让你看到一个更广阔的世界。尝试使用 YaCy，看看你发现了什么。</p><hr>',22)),r("p",null,[t[14]||(t[14]=a("via: ",-1)),o(e,{href:"https://opensource.com/article/20/2/yacy-search-engine-hacks"},{default:n(()=>[...t[13]||(t[13]=[a("https://opensource.com/article/20/2/yacy-search-engine-hacks",-1)])]),_:1})]),r("p",null,[t[19]||(t[19]=a("作者：",-1)),o(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[15]||(t[15]=[a("Seth Kenlon",-1)])]),_:1}),t[20]||(t[20]=a(" 选题：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[16]||(t[16]=[a("lujun9972",-1)])]),_:1}),t[21]||(t[21]=a(" 译者：",-1)),o(e,{href:"https://github.com/HankChow"},{default:n(()=>[...t[17]||(t[17]=[a("HankChow",-1)])]),_:1}),t[22]||(t[22]=a(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[18]||(t[18]=[a("wxy",-1)])]),_:1})]),r("p",null,[t[25]||(t[25]=a("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[23]||(t[23]=[a("LCTT",-1)])]),_:1}),t[26]||(t[26]=a(" 原创编译，",-1)),o(e,{href:"https://linux.cn/"},{default:n(()=>[...t[24]||(t[24]=[a("Linux中国",-1)])]),_:1}),t[27]||(t[27]=a(" 荣誉推出",-1))])])}const x=s(u,[["render",d]]);export{T as __pageData,x as default};
